def resolve(path, cwd, links):
    if path is None or cwd is None or links is None:
        return None

    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    if not cwd.startswith('/') or (cwd != '/' and cwd.endswith('/')):
        return None

    # Start with cwd if path is relative, otherwise start with '/'
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0
    max_links = 8

    while True:
        # Split remaining path into components
        components = remaining.split('/')
        remaining = ''

        for component in components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                continue

            # Append component to current path
            if current == '/':
                candidate = '/' + component
            else:
                candidate = current + '/' + component

            # Check if candidate is a symlink
            if candidate in links:
                link_count += 1
                if link_count > max_links:
                    return None

                target = links[candidate]

                # Resolve the target relative to the directory containing the link
                if target.startswith('/'):
                    current = '/'
                    remaining = target[1:]
                else:
                    current = candidate.rsplit('/', 1)[0]
                    remaining = target

                # Continue processing with the target
                break
            else:
                current = candidate
        else:
            # All components processed without hitting a symlink
            break

        if remaining == '':
            break

    # Return result without trailing slash, except for '/'
    if current == '/':
        return '/'
    else:
        return current

